#include "src/world_update_export.hpp"
#include "src/workspace.hpp"
#include <QtCore>
#include <iostream>
using namespace worlded;
static void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
static GameObject make(unsigned type,unsigned proto,unsigned x,unsigned y){GameObject o;o.type=type;o.prototype_id=proto;o=clone_instance(o);set_number(o,"LOCATION",std::uint64_t(x)|(std::uint64_t(y)<<32));set_number(o,"FLAGS",0);return o;}
static Sector blank(){Bytes bytes(4+4096*4+4+4+4,0);auto put=[&](unsigned p,unsigned n){for(unsigned i=0;i<4;i++)bytes[p+i]=n>>(8*i);};put(4+4096*4,1);put(4+4096*4+4,0xaa0000);Sector sector(bytes);sector.set_blocked(3,4,true);return sector;}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{QTemporaryDir root,projects;check(root.isValid() && projects.isValid(),"Temporary folders unavailable");auto game=std::filesystem::u8path(root.path().toStdString());auto folder=std::filesystem::u8path(projects.path().toStdString());auto original=make(3,100,65,130);set_number(original,"CURRENT_AID",0x40000000);Building native{BuildingPlan{},blank(),{original},{}};auto sector=native.sector();const std::string path="maps/test/134217729.sec";write_bytes(game/"data"/path,sector.encode());auto prototype=make(3,100,0,0);set_number(prototype,"FLAGS",0);write_bytes(game/"data/proto/000100 - scenery.pro",encode_instance(prototype));auto chestPrototype=make(2,300,0,0);write_bytes(game/"data/proto/000300 - chest.pro",encode_instance(chestPrototype));Installation installation(game);Building scene{BuildingPlan{},sector,{original},{}};scene.map_name="test";scene.sector_id=1ull|(2ull<<26);scene.existing_map=true;set_number(scene.objects[0],"LOCATION",1ull|(2ull<<32));capture_scene_reference(scene,installation,path,false);auto originalReference=encode_scene_reference(*scene.reference);check(scene.reference->origins[0].ordinal==0,"Original ordinal wrong");auto chest=make(2,300,9,10);set_number(chest,"CONTAINER_LOCK_DIFFICULTY",33);set_number(chest,"CONTAINER_INVENTORY_NUM",1);ObjectField list;list.name="CONTAINER_INVENTORY_LIST_IDX";list.kind="HANDLE_ARRAY";list.elements.push_back({0,inventory_id_bytes(make(8,800,0,0).id)});chest.fields.push_back(list);import_reference_mobile(scene,installation,{chest,"maps/test/original.mob",std::string(64,'0')});auto chestId=scene.objects.back().id;auto chestBefore=scene.objects.back();set_number(scene.objects.back(),"LOCATION",11ull|(12ull<<32));scene.ground.set_blocked(3,4,false);auto added=make(3,100,13,14);set_number(added,"CURRENT_AID",0x40000000);scene.objects.push_back(added);
    auto review=reviewWorldUpdate(scene,installation,"test.update","1.0.0",1);if(!review.unsupported.empty())throw std::runtime_error(review.unsupported.join("\n").toStdString());check(review.operations.size()==3,"Expected blocker + decor addition + chest movement only");unsigned moved=0,blocked=0,inserted=0;for(auto value:review.operations){auto op=value.toObject();moved+=op["kind"]=="move_object";blocked+=op["kind"]=="set_block";inserted+=op["kind"]=="add_object";if(op["kind"]=="move_object"){check(op["selector"].toObject()["guid"].toString().toStdString()==chestId,"Chest GUID changed");check(op["before"].toArray()[0].toString()==u64text(globalLocation(chestBefore.number("LOCATION"),scene.sector_id)),"Move precondition is not original location");}}check(moved==1 && blocked==1 && inserted==1,"Wrong operation kinds");
    auto prototypeScene=scene;auto freshPrototype=make(3,400,0,0);set_number(freshPrototype,"FLAGS",0x400);prototypeScene.prototypes["proto/000400 - new.pro"]=encode_instance(freshPrototype);auto inherited=make(3,400,20,20);inherited.fields.erase(std::remove_if(inherited.fields.begin(),inherited.fields.end(),[](const auto& f){return f.name=="FLAGS";}),inherited.fields.end());prototypeScene.objects.push_back(inherited);auto prototypeReview=reviewWorldUpdate(prototypeScene,installation,"test.proto","1.0.0",1);check(prototypeReview.unsupported.empty(),"New prototype failed review");auto inheritedPayload=read_objects(prototypeReview.resources.at("objects/"+inherited.id+".mob"));check(inheritedPayload.size()==1 && inheritedPayload[0].number("FLAGS")==0x2400,"New payload lost inherited prototype flags");publishWorldUpdate(prototypeScene,prototypeReview,folder/"prototype-r1");set_number(freshPrototype,"FLAGS",0);prototypeScene.prototypes["proto/000400 - new.pro"]=encode_instance(freshPrototype);check(!reviewWorldUpdate(prototypeScene,installation,"test.proto","1.1.0",2).unsupported.empty(),"Published prototype was silently replaced");
    auto project=folder/"scene";save_scene_project(scene,project);auto reopened=load_project(project);check(reopened.reference && reopened.reference->id==scene.reference->id,"Original reference lost on reopen");check(encode_scene_reference(*reopened.reference)==encode_scene_reference(*scene.reference),"Reference changed during save");std::set<std::string> beforeIds,afterIds;for(auto o:scene.objects)beforeIds.insert(o.editor_id);for(auto o:reopened.objects)afterIds.insert(o.editor_id);check(beforeIds==afterIds,"Authoring IDs changed during project roundtrip");
    publishWorldUpdate(reopened,review,folder/"package-r1");save_scene_project(reopened,project);auto published=load_project(project);auto prior=updateHistory(published)["manifest"].toObject();check(prior["operations"].toArray()==review.operations,"Published operation history changed");auto it=std::find_if(published.objects.begin(),published.objects.end(),[&](const auto& o){return o.id==chestId;});check(it!=published.objects.end(),"Chest vanished");check(it->number("CONTAINER_INVENTORY_NUM")==1 && it->number("CONTAINER_LOCK_DIFFICULTY")==33,"Move changed chest inventory or lock");set_number(*it,"LOCATION",15ull|(12ull<<32));auto second=reviewWorldUpdate(published,installation,"test.update","1.1.0",2);check(second.unsupported.empty() && second.operations.size()==4 && second.rows.size()==1,"Second revision did not retain old operations and add one incremental move");for(int i=0;i<3;i++)check(second.operations[i]==review.operations[i],"Published operation bytes would change");check(second.operations[3].toObject()["before"].toArray()[0]==review.operations[1].toObject()["after"].toArray()[0] || second.operations[3].toObject()["before"].toArray()[0]==review.operations[2].toObject()["after"].toArray()[0],"New revision does not compare last-published authoring state");
    auto refusesHistory=[&](){try{return !reviewWorldUpdate(published,installation,"test.update","1.1.0",2).unsupported.empty();}catch(const std::exception&){return true;}};
    auto validHistory=published.update_history;
    auto tampered=updateHistory(published);auto tamperedManifest=tampered["manifest"].toObject();auto tamperedOps=tamperedManifest["operations"].toArray();auto tamperedOp=tamperedOps[0].toObject();tamperedOp["id"]="rewritten-operation";tamperedOps[0]=tamperedOp;tamperedManifest["operations"]=tamperedOps;tampered["manifest"]=tamperedManifest;auto tamperedJson=QJsonDocument(tampered).toJson(QJsonDocument::Compact);published.update_history=Bytes(tamperedJson.begin(),tamperedJson.end());check(refusesHistory(),"Modified published operation history was accepted");published.update_history=validHistory;
    tampered=updateHistory(published);auto payloads=tampered["resource_data"].toObject();check(!payloads.isEmpty(),"Published addition payload missing");payloads[payloads.keys().front()]="Y29ycnVwdA==";tampered["resource_data"]=payloads;tamperedJson=QJsonDocument(tampered).toJson(QJsonDocument::Compact);published.update_history=Bytes(tamperedJson.begin(),tamperedJson.end());check(refusesHistory(),"Modified published payload was accepted");published.update_history=validHistory;
    set_number(*it,"CONTAINER_INVENTORY_NUM",2);check(!reviewWorldUpdate(published,installation,"test.update","1.1.0",2).unsupported.empty(),"Inventory overwrite silently exported");set_number(*it,"CONTAINER_INVENTORY_NUM",1);auto bytes=installation.read("proto/000100 - scenery.pro");bytes.back()^=1;write_bytes(game/"data/proto/000100 - scenery.pro",bytes);check(!reviewWorldUpdate(published,installation,"test.update","1.1.0",2).unsupported.empty(),"Installation drift was ignored");
    if(argc==2){auto destination=std::filesystem::u8path(argv[1]);check(!std::filesystem::exists(destination),"Fixture package output exists");std::filesystem::copy(folder/"package-r1",destination,std::filesystem::copy_options::recursive);}
    std::cout<<"PASS: immutable reference + selection roundtrip, guarded blocker/add/move, inventory preservation, cumulative revisions, unsupported mutations and source drift\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
